lessons.syntax:
if (s < 0 || s > 100) { /* invalid */ }
else if (s >= 60) { /* pass */ }
else { /* fail */ }

lessons.example:
#include <stdio.h>

int main(void) {
    int s = 120;
    if (s < 0 || s > 100) { puts("Invalid"); }
    else if (s >= 60) { puts("Pass"); }
    else { puts("Fail"); }
    return 0;
}

