lessons.example:
#include <stdio.h>
#include <stdbool.h>

int main(void) {
    bool open = true;
    int stock = 0;
    if (open) {
        if (stock > 0) { puts("Buy"); }
        else { puts("Sold out"); }
    } else { puts("Closed"); }
    return 0;
}
